#!/usr/bin/env python3
"""Checksum validation for all currently loaded Python modules.

The script walks ``sys.modules``, resolves each module's backing file when one
exists, computes a SHA-256 checksum, and validates it against an optional JSON
baseline. It is intentionally dependency-free so it can run early in an
application startup path.

Usage:
    python integrity_check.py --write-baseline module_checksums.json
    python integrity_check.py --baseline module_checksums.json

Without a baseline it prints a report and exits successfully unless a module
file cannot be read.
"""

from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import os
import sys
from dataclasses import asdict, dataclass
from pathlib import Path
from types import ModuleType
from typing import Dict, Iterable, Optional, Tuple


@dataclass(frozen=True)
class ModuleChecksum:
    """Checksum metadata for a loaded module backed by a readable file."""

    name: str
    path: str
    sha256: str
    size: int


@dataclass(frozen=True)
class ModuleReadError:
    """Details for a loaded module whose backing file could not be hashed."""

    name: str
    path: str
    error: str


def _normalise_module_path(module: ModuleType) -> Optional[Path]:
    """Return the filesystem path for a module, if it has one.

    Built-in, frozen, namespace, and dynamically-created modules often do not
    have a normal file to hash; those are skipped.
    """

    raw_path = getattr(module, "__file__", None)
    if not raw_path:
        return None

    path = Path(raw_path)

    # Hash source instead of bytecode when possible so checksums survive normal
    # .pyc cache regeneration.
    if path.suffix == ".pyc":
        source = importlib.util.source_from_cache(str(path))
        source_path = Path(source)
        if source_path.exists():
            path = source_path

    try:
        return path.resolve(strict=True)
    except FileNotFoundError:
        return path


def _sha256_file(path: Path, chunk_size: int = 1024 * 1024) -> Tuple[str, int]:
    digest = hashlib.sha256()
    size = 0
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(chunk_size), b""):
            size += len(chunk)
            digest.update(chunk)
    return digest.hexdigest(), size


def collect_loaded_module_checksums(
    modules: Optional[Dict[str, ModuleType]] = None,
) -> Tuple[Dict[str, ModuleChecksum], Dict[str, ModuleReadError], int]:
    """Hash all loaded modules that have backing files.

    Returns ``(checksums, errors, skipped_count)``.
    """

    modules = modules if modules is not None else dict(sys.modules)
    checksums: Dict[str, ModuleChecksum] = {}
    errors: Dict[str, ModuleReadError] = {}
    skipped = 0
    seen_paths: Dict[Path, str] = {}

    for name, module in sorted(modules.items()):
        if module is None:
            skipped += 1
            continue

        path = _normalise_module_path(module)
        if path is None:
            skipped += 1
            continue

        # Aliased modules can point at the same file. Keep both module names in
        # the report, but avoid reading the same file more than once.
        if path in seen_paths:
            original = checksums[seen_paths[path]]
            checksums[name] = ModuleChecksum(
                name=name,
                path=original.path,
                sha256=original.sha256,
                size=original.size,
            )
            continue

        try:
            sha256, size = _sha256_file(path)
        except OSError as exc:
            errors[name] = ModuleReadError(name=name, path=str(path), error=str(exc))
            continue

        checksums[name] = ModuleChecksum(
            name=name,
            path=str(path),
            sha256=sha256,
            size=size,
        )
        seen_paths[path] = name

    return checksums, errors, skipped


def load_baseline(path: Path) -> Dict[str, ModuleChecksum]:
    data = json.loads(path.read_text(encoding="utf-8"))
    modules = data.get("modules", data)
    return {
        name: ModuleChecksum(
            name=name,
            path=str(entry["path"]),
            sha256=str(entry["sha256"]),
            size=int(entry.get("size", 0)),
        )
        for name, entry in modules.items()
    }


def write_baseline(path: Path, checksums: Dict[str, ModuleChecksum]) -> None:
    payload = {
        "algorithm": "sha256",
        "python": sys.version,
        "executable": sys.executable,
        "modules": {name: asdict(value) for name, value in sorted(checksums.items())},
    }
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def validate_against_baseline(
    current: Dict[str, ModuleChecksum],
    baseline: Dict[str, ModuleChecksum],
) -> Dict[str, Dict[str, object]]:
    missing = sorted(set(baseline) - set(current))
    added = sorted(set(current) - set(baseline))
    changed = {}

    for name in sorted(set(current) & set(baseline)):
        old = baseline[name]
        new = current[name]
        if old.sha256 != new.sha256 or old.path != new.path:
            changed[name] = {
                "expected": asdict(old),
                "actual": asdict(new),
            }

    return {"missing": missing, "added": added, "changed": changed}


def print_report(
    checksums: Dict[str, ModuleChecksum],
    errors: Dict[str, ModuleReadError],
    skipped: int,
    validation: Optional[Dict[str, Dict[str, object]]] = None,
) -> None:
    print(f"Hashed modules: {len(checksums)}")
    print(f"Skipped modules without files: {skipped}")
    print(f"Read errors: {len(errors)}")

    if errors:
        print("\nUnreadable module files:")
        for error in errors.values():
            print(f"  - {error.name}: {error.path} ({error.error})")

    if validation is not None:
        missing = validation["missing"]
        added = validation["added"]
        changed = validation["changed"]
        print("\nBaseline validation:")
        print(f"  Missing modules: {len(missing)}")
        print(f"  Added modules: {len(added)}")
        print(f"  Changed modules: {len(changed)}")

        for label, values in (("missing", missing), ("added", added)):
            if values:
                print(f"\n{label.title()}:")
                for name in values:
                    print(f"  - {name}")

        if changed:
            print("\nChanged:")
            for name, detail in changed.items():
                expected = detail["expected"]
                actual = detail["actual"]
                print(f"  - {name}")
                print(f"      expected: {expected['sha256']} {expected['path']}")
                print(f"      actual:   {actual['sha256']} {actual['path']}")


def parse_args(argv: Iterable[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Checksum validate all currently loaded Python modules."
    )
    parser.add_argument(
        "--baseline",
        type=Path,
        help="JSON baseline to validate against.",
    )
    parser.add_argument(
        "--write-baseline",
        type=Path,
        help="Write the current checksums to this JSON file.",
    )
    parser.add_argument(
        "--strict-errors",
        action="store_true",
        help="Exit non-zero if any loaded module file cannot be read.",
    )
    return parser.parse_args(list(argv))


def main(argv: Iterable[str] = sys.argv[1:]) -> int:
    args = parse_args(argv)
    checksums, errors, skipped = collect_loaded_module_checksums()

    validation = None
    if args.baseline:
        validation = validate_against_baseline(checksums, load_baseline(args.baseline))

    if args.write_baseline:
        write_baseline(args.write_baseline, checksums)
        print(f"Wrote baseline: {args.write_baseline}")

    print_report(checksums, errors, skipped, validation)

    if args.strict_errors and errors:
        return 2

    if validation is not None:
        if validation["missing"] or validation["added"] or validation["changed"]:
            return 1

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

