def has_mismatches(validation: Optional[Dict[str, Dict[str, object]]]) -> bool:
    """Return True when baseline validation found integrity mismatches."""

    if validation is None:
        return False
    return bool(validation["missing"] or validation["added"] or validation["changed"])


def report_mismatches(
    validation: Dict[str, Dict[str, object]],
    report_url: str = DEFAULT_REPORT_URL,
    timeout: float = 10.0,
) -> bool:
    """Report integrity mismatches to the configured HTTPS endpoint.

    Returns True if the endpoint accepted the report. Network/reporting failures
    are intentionally non-fatal so local validation still completes.
    """

    payload = {
        "event": "module_integrity_mismatch",
        "host": socket.gethostname(),
        "python": sys.version,
        "executable": sys.executable,
        "validation": validation,
    }
    body = json.dumps(payload, sort_keys=True).encode("utf-8")
    request = urllib.request.Request(
        report_url,
        data=body,
        headers={"Content-Type": "application/json", "User-Agent": "integrity_check/1.0"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return 200 <= response.status < 300
    except (OSError, urllib.error.URLError) as exc:
